import { useState } from 'react';
import LocalSearchImage from './LocalSearchImage';

/**
 * Phase 38 — RAG Answer Results Component
 *
 * Displays the conversational answer generated by the LLM (Gemini Flash 2.5 via LangChain)
 * alongside the photos returned by the RAG pipeline.
 *
 * The browser resolves the returned imageIds entirely on-device from local folder handles.
 * Zero photo binaries or paths are ever transmitted over the network.
 */
export default function RagAnswerResults({
    message = '',
    question = '',
    images = [],
    loading = false,
    onClear = () => {}
}) {
    const [failedIds, setFailedIds] = useState(new Set());

    const availableImages = images.filter(
        item => item && item.success !== false && !failedIds.has(item.imageId)
    );

    if (loading) {
        return (
            <div style={{
                textAlign: 'center',
                padding: '48px 24px',
                backgroundColor: 'var(--bg-surface)',
                borderRadius: 'var(--radius)',
                border: '1px solid var(--border-color)',
                marginBottom: '24px'
            }}>
                <div style={{ fontSize: '2rem', marginBottom: '12px' }}>🤖</div>
                <h3 style={{ fontSize: '1.1rem', fontWeight: 600, color: 'var(--text-primary)' }}>
                    Asking Stash AI...
                </h3>
                <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginTop: '4px' }}>
                    Searching private vector index in Pinecone and synthesizing answer with Gemini Flash 2.5.
                </p>
            </div>
        );
    }

    return (
        <div style={{ marginBottom: '32px' }}>
            {/* AI Conversational Answer Card */}
            <div style={{
                backgroundColor: 'var(--bg-surface)',
                border: '1px solid #38bdf8',
                borderRadius: 'var(--radius)',
                padding: '20px 24px',
                marginBottom: '20px',
                boxShadow: '0 4px 12px rgba(56, 189, 248, 0.08)'
            }}>
                <div style={{
                    display: 'flex',
                    alignItems: 'flex-start',
                    justifyContent: 'space-between',
                    gap: '16px',
                    flexWrap: 'wrap'
                }}>
                    <div style={{ display: 'flex', alignItems: 'flex-start', gap: '14px', flex: 1, minWidth: '260px' }}>
                        <div style={{
                            width: '40px',
                            height: '40px',
                            borderRadius: '10px',
                            backgroundColor: 'rgba(56, 189, 248, 0.12)',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            fontSize: '1.3rem',
                            flexShrink: 0
                        }}>
                            🤖
                        </div>
                        <div>
                            <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', marginBottom: '4px' }}>
                                Question: <strong style={{ color: 'var(--text-primary)' }}>&ldquo;{question}&rdquo;</strong>
                            </div>
                            <div style={{
                                fontSize: '1.05rem',
                                color: 'var(--text-primary)',
                                lineHeight: 1.5,
                                fontWeight: 500,
                                marginTop: '4px'
                            }}>
                                {message}
                            </div>
                            <div style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: '8px',
                                marginTop: '10px',
                                fontSize: '0.72rem',
                                color: 'var(--text-muted)'
                            }}>
                                <span style={{
                                    backgroundColor: 'rgba(16, 185, 129, 0.1)',
                                    color: '#10b981',
                                    padding: '2px 8px',
                                    borderRadius: '10px',
                                    fontWeight: 600
                                }}>
                                    🔒 Private RAG
                                </span>
                                <span>&bull;</span>
                                <span>Resolved {availableImages.length} photo{availableImages.length === 1 ? '' : 's'} on-device</span>
                            </div>
                        </div>
                    </div>

                    <button
                        onClick={onClear}
                        className="btn-logout"
                        style={{ fontSize: '0.85rem', padding: '6px 14px' }}
                    >
                        ✕ Clear
                    </button>
                </div>
            </div>

            {/* Resolved Photos Grid */}
            {availableImages.length > 0 && (
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))',
                    gap: '20px'
                }}>
                    {availableImages.map((item) => (
                        <div
                            key={item.imageId}
                            style={{
                                backgroundColor: 'var(--bg-surface)',
                                border: '1px solid var(--border-color)',
                                borderRadius: 'var(--radius)',
                                overflow: 'hidden',
                                display: 'flex',
                                flexDirection: 'column',
                                boxShadow: 'var(--shadow-subtle)',
                                position: 'relative'
                            }}
                        >
                            {/* On-device photo resolution */}
                            <div style={{ width: '100%', height: '190px', backgroundColor: '#0f172a' }}>
                                <LocalSearchImage
                                    imageId={item.imageId}
                                    initialBlobUrl={item.blobUrl}
                                    alt={item.record?.caption || 'RAG matched photo'}
                                    onFailed={() => setFailedIds(prev => new Set(prev).add(item.imageId))}
                                />
                            </div>

                            {/* Card Details */}
                            <div style={{ padding: '12px 14px', flex: 1, display: 'flex', flexDirection: 'column' }}>
                                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '4px' }}>
                                    <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)', fontFamily: 'monospace' }}>
                                        ID: {item.imageId.slice(0, 12)}...
                                    </span>
                                    <span style={{ fontSize: '0.68rem', color: '#10b981', fontWeight: 600 }}>
                                        ✓ Resolved Locally
                                    </span>
                                </div>

                                {item.record?.caption && (
                                    <p style={{
                                        fontSize: '0.82rem',
                                        color: 'var(--text-primary)',
                                        lineHeight: 1.4,
                                        marginTop: '4px',
                                        display: '-webkit-box',
                                        WebkitLineClamp: 3,
                                        WebkitBoxOrient: 'vertical',
                                        overflow: 'hidden'
                                    }}>
                                        &ldquo;{item.record.caption}&rdquo;
                                    </p>
                                )}

                                {item.record?.keywords && item.record.keywords.length > 0 && (
                                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px', marginTop: '8px' }}>
                                        {item.record.keywords.slice(0, 3).map((kw) => (
                                            <span
                                                key={kw}
                                                style={{
                                                    fontSize: '0.65rem',
                                                    padding: '2px 6px',
                                                    borderRadius: '4px',
                                                    backgroundColor: '#f1f5f9',
                                                    color: '#475569',
                                                    border: '1px solid #e2e8f0'
                                                }}
                                            >
                                                #{kw}
                                            </span>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

